export interface LoopOptions {
  targetDir: string;
  faults: string[] | 'all';
  fixer: 'auto' | 'playbook' | 'claude';
  redTrials: number;
  judgeTrials: number;
  seed: number;
  maxAttempts: number;
  memory: boolean;
  brain: BrainMode;
