}

export const DEFAULT_LOOP: Omit<LoopOptions, 'targetDir'> = {
  faults: 'all',
  fixer: 'auto',
  redTrials: 20,
  judgeTrials: 40,
  seed: 42,
  maxAttempts: 4,
  memory: true,
  brain: 'simulated',
  deadlineMs: 5000,
  maxSteps: 50,
  stateDir: '.bulwark',
  readbackWaitMs: Number(process.env.BULWARK_NEATLOGS_WAIT_MS ?? 20_000),
};

export type LoopEvent =
  | { type: 'run-start'; runId: string; target: string; fixer: string; faults: string[]; redTrials: number; judgeTrials: number }
  | { type: 'analyze'; findings: Finding[]; provenance?: Provenance[] }
  | { type: 'scorecard'; phase: 'before' | 'after'; results: ExperimentResult[]; overall: number; ws?: string }
  | { type: 'fault-start'; fault: string; title: string; hypothesis: string }
  | { type: 'fault-skip'; fault: string; reason: string }
  | ({ type: 'observe' } & ObserveRecord)
  | { type: 'checkpoint'; action: 'save' | 'restore'; id: string; label: string }
  | { type: 'slo-plan'; plans: SloPlan[]; confidence: number; method: string }
  | { type: 'attempt'; fault: string; n: number; strategy: string; title: string; rationale: string; author: string; diff: string; added: number; removed: number; round?: number }
  | { type: 'verdict'; fault: string; n: number; status: VerdictStatus; reasons: string[]; pValue: number; afterPassed: number; trials: number; regressions: Regression[]; slo?: SloResult; overhead?: Overhead; author?: string; round?: number }
  | ({ type: 'tournament' } & TournamentResult)
  | { type: 'mutation'; fault: string; ok: boolean; unfixedPassed: number; fixedPassed: number; trials: number }
  | { type: 'fault-done'; fault: string; status: FaultRecord['status']; attempts: number }
  | { type: 'residual'; findings: Finding[] }
  | { type: 'log'; message: string }
  | { type: 'run-done'; summary: LoopSummary };

export interface LoopSummary {
  runId: string;
  dir: string;
  target: string;
  fixer: string;
  overallBefore: number;
  overallAfter: number;
  fixed: string[];
  unfixed: string[];
  skipped: string[];
  attempts: number;
  rollbacks: number;
  /** Weak links the analyzer still sees in the final code. Reported, never hidden. */
  residual: Finding[];
  artifacts: { patch: string; pr: string; badge: string; postmortems: string[] };
  finalFiles: Files;
  targetRel: string;
  /** What this run spent: LLM tokens (priced) plus compute time. */
  cost?: CostSummary;
}

export async function runLoop(input: Partial<LoopOptions> & { targetDir: string }, emit: (e: LoopEvent) => void): Promise<LoopSummary> {
  const o: LoopOptions = { ...DEFAULT_LOOP, ...input };
  const runId = new Date().toISOString().replace(/[:.]/g, '-');
  const dir = join(o.stateDir, 'runs', runId);
  const ws = new Workspace(join(dir, 'ws'), o.targetDir);
  const checkpoints = new CheckpointStore(join(dir, 'checkpoints'));
  const memory = new StrategyMemory(join(o.stateDir, 'memory.json'));
  // A tournament replaces the single fixer with several entrants; validate them up front.
  const entrants: Fixer[] | undefined = o.tournament?.map(createEntrant);
  const fixer: Fixer = entrants ? { name: tournamentName(o.tournament!), propose: async () => null } : createFixer(o.fixer);
  const targetRel = relative(process.cwd(), resolve(o.targetDir));

  // Each phase is its own root trace, grouped into one neatlogs session per run,
  // so "before" and "after" are separate traces you can open and compare.
  const phase = <T>(name: string, attributes: Record<string, unknown>, fn: () => Promise<T>) =>
    trace({ name, kind: 'WORKFLOW', sessionId: `bulwark-${runId}`, sessionFeatureName: 'bulwark-loop', attributes: { runId, target: targetRel, fixer: fixer.name, ...attributes } }, fn);

  // Every LLM call and trial inside this run is counted on its own meter.
  const meter = new CostMeter();
  return meter.run(async () => {
    const original = await loadTarget(o.targetDir);
    const originalFiles = readFiles(o.targetDir, original.editableFiles);
    const scope: Fault[] = o.faults === 'all' ? FAULTS : o.faults.map(getFault);
    const rules = compileRules(original.rules).compiled.map(({ rule, how }) => ({ rule, how }));
    const sloPlans = planSlo(o.slo, scope.map((f) => f.id));
    emit({ type: 'run-start', runId, target: original.name, fixer: fixer.name, faults: scope.map((f) => f.id), redTrials: o.redTrials, judgeTrials: o.judgeTrials });
    if (o.slo && sloPlans.length) emit({ type: 'slo-plan', plans: sloPlans, confidence: o.slo.confidence, method: sloPlans[0].method });

    // Red: find weak links, then measure the damage.
    const findings = await phase('1 red: analyze code', {}, async () => analyzeTarget(o.targetDir, original));
    // Provenance: which commit, and which Entire session and prompt, introduced each weak link.
    const provenance = attachProvenance(findings, o.targetDir);
    // Entire Graph: blast radius per weak link, and (below) fix-site search per fault. Queries run
    // against the original target in the repo: the loop's patched copies live in
    // .bulwark/runs/<id>/ws/, which is gitignored and outside the tree the graph indexes.
    const graph = targetRel.startsWith('..') ? undefined : graphFor(process.cwd());
    const blasts = attachBlast(findings, graph, targetRel);
    emit({ type: 'analyze', findings, provenance });
    emit({
      type: 'log',
      message: graph
        ? `Entire Graph: blast radius for ${blasts}/${findings.length} weak links`
        : `Entire Graph ${process.env.BULWARK_ENTIRE_GRAPH === '0' ? 'switched off (BULWARK_ENTIRE_GRAPH=0)' : 'not available (needs the `entire graph` plugin)'}; using static analysis only`,
    });

    const redOpts = { trials: o.redTrials, seed: o.seed, brain: o.brain, deadlineMs: o.deadlineMs, maxSteps: o.maxSteps };
    const before = await phase('2 red: attack scorecard BEFORE', { phase: 'before', trials: o.redTrials, seed: o.seed }, () => runAll(original, redOpts));
    emit({ type: 'scorecard', phase: 'before', results: Object.values(before), overall: overallPassRate(before) });

    // The Judge uses its own seeds, so a fix can't be tuned to the trials Red happened to run.
    const judgeOpts = { ...redOpts, trials: o.judgeTrials, seed: o.seed + 1_000_003 };
    emit({ type: 'log', message: `Judge measuring the unpatched code on fresh seeds (${o.judgeTrials} trials per fault)` });
    let baseFiles = originalFiles;
    let baseDir = o.targetDir;
    let baseTarget: BulwarkTarget = original;
    let baseResults = await phase('judge: measure unpatched code', { trials: o.judgeTrials }, () => runAll(original, judgeOpts));

    const highRisk = (f: Fault) => findings.some((x) => x.faults.includes(f.id) && x.severity === 'high');
    const ordered = [...scope].sort((a, b) => Number(highRisk(b)) - Number(highRisk(a)));
    const records: FaultRecord[] = [];
    let attempts = 0;
    let rollbacks = 0;
    const readbackWaitMs = Number.isFinite(o.readbackWaitMs) ? Math.max(0, o.readbackWaitMs!) : 20_000;
    const readCache = new Map<string, ReadResult>();
    const targetHash = hashFiles(originalFiles);
    const previous = previousFailures(o.stateDir, targetHash);

    for (const fault of ordered) {
      emit({ type: 'fault-start', fault: fault.id, title: fault.title, hypothesis: fault.hypothesis });
      const rec: FaultRecord = {
        fault: fault.id,
        title: fault.title,
        hypothesis: fault.hypothesis,
        status: 'unfixed',
        findings: findings.filter((f) => f.faults.includes(fault.id)),
        attempts: [],
      };
      records.push(rec);

      const skip =
        before[fault.id].passed === before[fault.id].trials
          ? 'already resilient: every trial passed'
          : baseResults[fault.id].passed === baseResults[fault.id].trials
            ? 'already resilient after earlier fixes in this run'
            : undefined;
      if (skip) {
        rec.status = 'skipped';
        rec.skipReason = skip;
        emit({ type: 'fault-skip', fault: fault.id, reason: skip });
        emit({ type: 'fault-done', fault: fault.id, status: rec.status, attempts: 0 });
        continue;
      }

      rec.before = baseResults[fault.id];

      // Observe: read a failing trial back from neatlogs. Oldest trace first: the previous run's on
      // the same code (minutes old), then this run's BEFORE scorecard (it ran earliest), then the
      // Judge's baseline; if no sampled trial failed, one failing seed is replayed traced.
      const candidates: ObserveCandidate[] = [
        ...(previous[fault.id] ?? []).map((e) => ({ seed: e.seed, traceId: e.traceId, source: 'previous' as const })),
        ...before[fault.id].examples.map((e) => ({ seed: e.seed, traceId: e.traceId, source: 'before' as const })),
        ...baseResults[fault.id].examples.map((e) => ({ seed: e.seed, traceId: e.traceId, source: 'judge' as const })),
      ];
      const observed = await observeFailure({
        fault: fault.id,
        candidates,
        waitMs: readbackWaitMs,
        cache: readCache,
        rerun: async (seed) => {
          const obs = await phase(`observe: replay failing ${fault.id} trial (seed ${seed})`, { fault: fault.id, seed }, () =>
            runTrial({ target: original, fault, seed, brain: o.brain, deadlineMs: o.deadlineMs, maxSteps: o.maxSteps, traced: true }),
          );
          await flush().catch(() => false);
          return obs.traceId;
        },
      });
      rec.observe = observed.record;
      emit({ type: 'observe', ...observed.record });
      // Entire Graph fix-site search for this fault, limited to the target's own files.
      const graphHints = graph?.search(fault.hypothesis, 3, targetRel) ?? undefined;

      const failed: FailedAttempt[] = [];
      const slo = sloPlans.find((p) => p.fault === fault.id);
      for (let round = 1; round <= o.maxAttempts; round++) {
        const cp = checkpoints.save(`before ${fault.id} ${entrants ? 'round' : 'attempt'} ${round}`, baseFiles, { fault: fault.id, attempt: round });
        emit({ type: 'checkpoint', action: 'save', id: cp.id, label: cp.label });

        const ctx = { fault, findings: rec.findings, files: baseFiles, before: baseResults[fault.id], failed, rules, preferred: o.memory ? memory.ranked(fault.kind) : [], neatlogsEvidence: observed.evidence, graphHints };
        const entries: Entry[] = await phase(`3 blue: propose fix for ${fault.id} #${round}`, { fault: fault.id, attempt: round, ...(entrants ? { tournament: true } : {}) }, async () =>
          entrants ? proposeAll(entrants, ctx) : [{ entrant: fixer.name, proposal: await fixer.propose(ctx) }],
        );
        if (!entries.some((e) => e.proposal)) {
          emit({ type: 'log', message: `Blue has no further strategies for ${fault.id}${entrants ? ` (${entries.map((e) => `${e.entrant}: ${e.error}`).join('; ')})` : ''}` });
          break;
        }

        // The Judge verifies every candidate one at a time, so latency measurements don't compete for the CPU.
        const candidates: { entry: Entry; v?: Verdict; diffSize: number; n?: number }[] = [];
        for (const entry of entries) {
          const proposal = entry.proposal;
          if (!proposal) {
            candidates.push({ entry, diffSize: 0 });
            continue;
          }
          attempts++;
          const n = rec.attempts.length + 1;
          const diff = diffFiles(baseFiles, proposal.files, `${targetRel}/`);
          const stats = diffStats(diff);
          emit({ type: 'attempt', fault: fault.id, n, strategy: proposal.strategy, title: proposal.title, rationale: proposal.rationale, author: proposal.author, diff, ...stats, ...(entrants ? { round } : {}) });

          const candidateDir = ws.materialize(`${fault.id}-a${n}`, proposal.files);
          const v = await phase(`4 judge: verify ${fault.id} #${n}`, { fault: fault.id, attempt: n, strategy: proposal.strategy }, () =>
            judge({ fault, candidate: () => loadTarget(candidateDir), baseResults, opts: judgeOpts, slo, budgets: o.budgets }),
          );
          emit({
            type: 'verdict', fault: fault.id, n, status: v.status, reasons: v.reasons, pValue: v.pValue, afterPassed: v.after.passed, trials: v.after.trials, regressions: v.regressions,
            ...(v.slo ? { slo: v.slo } : {}), ...(v.overhead ? { overhead: v.overhead } : {}), ...(entrants ? { author: proposal.author, round } : {}),
          });
          rec.attempts.push({
            n,
            strategy: proposal.strategy,
            title: proposal.title,
            rationale: proposal.rationale,
            author: proposal.author,
            diff,
            checkpoint: cp.id,
            verdict: { status: v.status, reasons: v.reasons, pValue: v.pValue, afterPassed: v.after.passed, trials: v.after.trials, ...(v.slo ? { slo: v.slo } : {}), ...(v.overhead ? { overhead: v.overhead } : {}) },
          });
          memory.record(fault.kind, proposal.strategy, v.status === 'fixed');
          candidates.push({ entry, v, diffSize: stats.added + stats.removed, n });
        }

        let chosen = candidates.find((c) => c.v?.status === 'fixed');
        if (entrants) {
          const { ranking, winner } = rankContenders(
            candidates.map((c) => ({
              entrant: c.entry.entrant,
              status: c.v?.status ?? 'no-proposal',
              strategy: c.entry.proposal?.strategy,
              title: c.entry.proposal?.title,
              ...(c.v?.slo ? { sloDemonstrated: c.v.slo.demonstrated } : {}),
              ...(c.v?.overhead ? { overhead: c.v.overhead } : {}),
              diffSize: c.diffSize,
              summary: c.v?.reasons[0] ?? c.entry.error,
            })),
          );
          const t: TournamentResult = { fault: fault.id, round, entrants: entries.map((e) => e.entrant), ranking, ...(winner ? { winner } : {}) };
          (rec.tournament ??= []).push(t);
          for (const r of ranking) {
            const c = candidates.find((x) => x.entry.entrant === r.entrant);
            const a = c?.n !== undefined ? rec.attempts.find((x) => x.n === c.n) : undefined;
            if (a) a.tournament = { round, rank: r.rank, outcome: r.outcome, reason: r.reason };
          }
          emit({ type: 'tournament', ...t });
          chosen = winner ? candidates.find((c) => c.entry.entrant === winner) : undefined;
        }

        if (chosen?.v && chosen.entry.proposal) {
          const proposal = chosen.entry.proposal;
          const v = chosen.v;
          // Guard: ship a regression test and prove it fails without the fix.
          const spec: ChaosSpec = { fault: fault.id, trials: o.judgeTrials, seed: o.seed + 2_000_003, strategy: proposal.strategy, createdBy: 'bulwark' };
          const fixedFiles = withSpec(proposal.files, spec);
          const fixedDir = ws.materialize(`${fault.id}-accepted`, fixedFiles);
          const fixedTarget = await loadTarget(fixedDir);
          const m = await phase(`5 guard: prove regression test for ${fault.id}`, { fault: fault.id }, () =>
            mutationCheck(spec, baseTarget, fixedTarget, judgeOpts),
          );
          rec.mutation = { ok: m.ok, unfixedPassed: m.unfixed.passed, fixedPassed: m.fixed.passed, trials: spec.trials };
          emit({ type: 'mutation', fault: fault.id, ...rec.mutation });

          baseFiles = fixedFiles;
          baseDir = fixedDir;
          baseTarget = fixedTarget;
          baseResults = v.results;
          rec.status = 'fixed';
          break;
        }

        for (const c of candidates) {
          if (c.entry.proposal && c.v) failed.push({ strategy: c.entry.proposal.strategy, author: c.entry.proposal.author, rationale: c.entry.proposal.rationale, reasons: c.v.reasons });
        }
        baseFiles = checkpoints.restore(cp.id);
        rollbacks++;
        emit({ type: 'checkpoint', action: 'restore', id: cp.id, label: cp.label });
      }
      emit({ type: 'fault-done', fault: fault.id, status: rec.status, attempts: rec.attempts.length });
    }

    // Red re-runs its original attack, same seeds, against the final code.
    const after = await phase('6 red: attack scorecard AFTER', { phase: 'after', trials: o.redTrials, seed: o.seed }, () => runAll(baseTarget, redOpts));
    // ws: the workspace holding the final code, so the dashboard can replay "after" trials against it.
    emit({ type: 'scorecard', phase: 'after', results: Object.values(after), overall: overallPassRate(after), ...(baseDir !== o.targetDir ? { ws: basename(baseDir) } : {}) });
    const residual = analyzeTarget(baseDir, baseTarget);
    emit({ type: 'residual', findings: residual });
    // One last look at neatlogs traces that weren't finalized when Blue needed them, for the postmortems.
    const late = await recheckPending(records.map((r) => r.observe), { cache: readCache });
    if (records.some((r) => r.observe?.traceId)) {
      const read = records.filter((r) => r.observe?.status === 'read').length;
      emit({ type: 'log', message: `neatlogs read-back: ${read}/${records.filter((r) => r.observe).length} failing-trial traces read${late ? ` (${late} only at the end of the run)` : ''}` });
    }

    const book = await loadPriceBook({ provider: llmProvider(), cachePath: join(o.stateDir, 'pricing-0g.json') });
    const cost = meter.summarize(book.priceFor, `0G router prices (${book.zgSource}); Anthropic-direct static table`);

    // Artifacts.
    mkdirSync(dir, { recursive: true });
    const patch = diffFiles(originalFiles, baseFiles, `${targetRel}/`);
    const traces = process.env.NEATLOGS_API_KEY ? 'exported to neatlogs (workflow "bulwark")' : 'local only (set NEATLOGS_API_KEY to export)';
    const artifacts = {
      patch: join(dir, 'fix.patch'),
      pr: join(dir, 'PR.md'),
      badge: join(dir, 'badge.svg'),
      postmortems: records.map((r) => join(dir, `postmortem-${r.fault}.md`)),
    };
    writeFileSync(artifacts.patch, patch);
    writeFileSync(artifacts.pr, prBody({ target: original.name, runId, records, before, after, diff: patch, traces, residual, provenance, cost }));
    writeFileSync(artifacts.badge, badgeSvg(overallPassRate(after)));
    records.forEach((r, i) => writeFileSync(artifacts.postmortems[i], postmortem(r, runId)));
    const meta = { run: runId, trials: o.redTrials, seed: o.seed };
    writeFileSync(join(dir, 'scorecard-before.md'), renderMarkdown(original, Object.values(before), meta));
    writeFileSync(join(dir, 'scorecard-after.md'), renderMarkdown(original, Object.values(after), meta));
    copyFileSync(artifacts.badge, join(o.stateDir, 'badge.svg'));
    if (o.memory) memory.save();

    const summary: LoopSummary = {
      runId,
      dir,
      target: original.name,
      fixer: fixer.name,
      overallBefore: overallPassRate(before),
      overallAfter: overallPassRate(after),
      fixed: records.filter((r) => r.status === 'fixed').map((r) => r.fault),
      unfixed: records.filter((r) => r.status === 'unfixed').map((r) => r.fault),
      skipped: records.filter((r) => r.status === 'skipped').map((r) => r.fault),
      attempts,
      rollbacks,
      residual,
      artifacts,
      finalFiles: baseFiles,
      targetRel,
      cost,
    };
    writeFileSync(join(dir, 'summary.json'), JSON.stringify({ ...summary, targetHash, records, before, after }, null, 2));
    writeFileSync(join(o.stateDir, 'latest.json'), JSON.stringify({ runId, dir }, null, 2));
    emit({ type: 'run-done', summary });
    return summary;
  });
}

/** Content hash of the target's editable files, so a later run knows whether a past trace shows the same code. */
export function hashFiles(files: Files): string {
  const h = createHash('sha256');
  for (const path of Object.keys(files).sort()) h.update(`${path}\0${files[path]}\0`);
  return h.digest('hex').slice(0, 16);
}

/** The previous run's traced failing trials per fault, when it attacked exactly this code. */
export function previousFailures(stateDir: string, targetHash: string): Record<string, { seed: number; traceId: string }[]> {
  try {
    const { dir } = JSON.parse(readFileSync(join(stateDir, 'latest.json'), 'utf8')) as { dir: string };
    const prev = JSON.parse(readFileSync(join(dir, 'summary.json'), 'utf8')) as { targetHash?: string; before?: Record<string, ExperimentResult> };
    if (prev.targetHash !== targetHash || !prev.before) return {};
    return Object.fromEntries(
      Object.entries(prev.before).map(([fault, r]) => [fault, r.examples.flatMap((e) => (e.traceId ? [{ seed: e.seed, traceId: e.traceId }] : []))]),
    );
  } catch {
    return {};
  }
}

function git(args: string[], cwd?: string): string {
  const res = spawnSync('git', args, { cwd, encoding: 'utf8' });
  if (res.status !== 0) throw new Error(`git ${args.join(' ')} failed: ${res.stderr.trim()}`);
  return res.stdout.trim();
}

/** Commits the verified fixes to a new branch via a throwaway worktree; the current checkout is untouched. */
export function applyAsBranch(summary: LoopSummary, stateDir = '.bulwark'): string {
  const branch = `bulwark/fix-${summary.runId}`;
  const wt = resolve(stateDir, 'worktrees', summary.runId);
  git(['worktree', 'add', '-q', '-b', branch, wt, 'HEAD']);
  try {
    for (const [path, content] of Object.entries(summary.finalFiles)) {
      const dest = join(wt, summary.targetRel, path);
      mkdirSync(join(dest, '..'), { recursive: true });
      writeFileSync(dest, content);
    }
    git(['add', '-A'], wt);
    git(['commit', '-q', '-m', `Bulwark: verified resilience fixes for ${summary.target}\n\nFixed: ${summary.fixed.join(', ') || 'none'}\nRun: ${summary.runId}`], wt);
  } finally {
    git(['worktree', 'remove', '--force', wt]);
  }
  return branch;
}

/** Pushes the branch and opens a PR with the Bulwark report as its body. */
export function openPullRequest(branch: string, summary: LoopSummary): string {
  git(['push', '-u', 'origin', branch]);
  const res = spawnSync('gh', ['pr', 'create', '--head', branch, '--title', `Bulwark: resilience fixes for ${summary.target}`, '--body-file', summary.artifacts.pr], { encoding: 'utf8' });
  if (res.status !== 0) throw new Error(`gh pr create failed: ${res.stderr.trim()}`);
  return res.stdout.trim();
}

// Local site: npm run dashboard → http://localhost:5317 (landing page), /app (dashboard)
// Streams chaos experiments to the browser as trials finish (Server-Sent Events).

import './env';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createServer, type ServerResponse } from 'node:http';
import { target } from '../targets/refundbot/bulwark.target';
import { FAULTS, getFault, type Fault } from './chaos/faults';
import { parseSlo } from './judge/slo';
import { parseTournament } from './judge/tournament';
import { runLoop } from './loop/orchestrator';
import { replayFromParams } from './replay';
import { runExperiment } from './scorecard';
import { defaultModel, llmLabel, llmProvider } from './llm';
import { initTracing } from './tracing';

const PORT = Number(process.env.PORT ?? 5317);
const PAGES: Record<string, URL> = {
  '/': new URL('./dashboard/landing.html', import.meta.url),
  '/app': new URL('./dashboard/index.html', import.meta.url),
};

function send(res: ServerResponse, event: string, data: unknown) {
  res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

async function streamRun(res: ServerResponse, params: URLSearchParams) {
  res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', connection: 'keep-alive' });
  const faultParam = params.get('fault') ?? 'all';
  const faults: (Fault | undefined)[] = faultParam === 'all' ? [undefined, ...FAULTS] : [undefined, getFault(faultParam)];
  const opts = {
    trials: Math.min(200, Math.max(1, Number(params.get('trials') ?? 20))),
    seed: Number(params.get('seed') ?? 42),
    brain: 'simulated' as const,
    deadlineMs: 5000,
    maxSteps: 50,
    sessionId: `chaos-${new Date().toISOString().replace(/[:.]/g, '-')}`,
  };

  // Experiments run concurrently so the whole board fills in at once.
  await Promise.all(
    faults.map(async (fault) => {
      const id = fault?.id ?? 'baseline';
      send(res, 'experiment-start', { fault: id, trials: opts.trials });
      const result = await runExperiment(target, fault, {
        ...opts,
        onTrial: ({ index, obs, broken }) =>
          send(res, 'trial', {
            fault: id,
            index,
            outcome: obs.outcome,
            passed: broken.length === 0,
            broken,
            seed: obs.seed,
            durationMs: Math.round(obs.durationMs),
            steps: obs.steps,
            refunds: obs.refunds.map((r) => r.amount),
            error: obs.error,
          }),
      });
      send(res, 'experiment-done', result);
    }),
  );
  send(res, 'done', {});
  res.end();
}

let loopRunning = false;

async function streamLoop(res: ServerResponse, params: URLSearchParams) {
  res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', connection: 'keep-alive' });
  if (loopRunning) {
    send(res, 'loop-error', { message: 'A Bulwark loop is already running. Wait for it to finish.' });
    return res.end();
  }
  loopRunning = true;
  try {
    // Optional: a reliability target (e.g. slo=0.95) and a fix tournament (e.g. tournament=playbook,playbook-strong).
    const slo = params.get('slo') ? parseSlo(params.get('slo')!) : undefined;
    const tournament = params.get('tournament') ? parseTournament(params.get('tournament')!) : undefined;
    await runLoop(
      {
        targetDir: 'targets/refundbot',
        // neatlogs read-back wait per fault: short by default so the live demo stays snappy (wait=0 to skip).
        readbackWaitMs: Math.min(60_000, Math.max(0, Number(params.get('wait') ?? process.env.BULWARK_NEATLOGS_WAIT_MS ?? 5000))),
        ...(slo ? { slo } : {}),
        ...(tournament ? { tournament } : {}),
        memory: params.get('memory') === '1',
        redTrials: Math.min(100, Math.max(5, Number(params.get('trials') ?? 20))),
        seed: Number(params.get('seed') ?? 42),
      },
      (e) => send(res, 'loop', e.type === 'run-done' ? { ...e, summary: { ...e.summary, finalFiles: undefined } } : e),
    );
  } catch (err) {
    send(res, 'loop-error', { message: err instanceof Error ? err.message : String(err) });
  } finally {
    loopRunning = false;
    res.end();
  }
}

const ARTIFACT_TYPES: Record<string, string> = {
  md: 'text/markdown; charset=utf-8',
  patch: 'text/plain; charset=utf-8',
  json: 'application/json',
  svg: 'image/svg+xml',
};

function serveArtifact(res: ServerResponse, params: URLSearchParams) {
  const run = params.get('run') ?? '';
  const file = params.get('file') ?? '';
  const ext = file.split('.').pop() ?? '';
  const path = join('.bulwark', 'runs', run, file);
  if (!/^[\w-]+$/.test(run) || !/^[\w.-]+$/.test(file) || !(ext in ARTIFACT_TYPES) || !existsSync(path)) {
    return res.writeHead(404).end('not found');
  }
  res.writeHead(200, { 'content-type': ARTIFACT_TYPES[ext] });
  res.end(readFileSync(path));
}

async function main() {
  const exporting = await initTracing('bulwark-dashboard');

  createServer((req, res) => {
    const url = new URL(req.url ?? '/', `http://localhost:${PORT}`);
    if (url.pathname in PAGES) {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(readFileSync(PAGES[url.pathname]));
    } else if (url.pathname === '/api/meta') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(
        JSON.stringify({
          target: target.name,
          rules: target.rules,
          neatlogs: exporting,
          fixer: llmProvider() ? `${defaultModel('fixer')} via ${llmLabel()} + playbook` : 'playbook (add an LLM key for Claude)',
          faults: [
            { id: 'baseline', title: 'No fault injected', hypothesis: 'The agent works when nothing breaks.' },
            ...FAULTS.map(({ id, title, hypothesis }) => ({ id, title, hypothesis })),
          ],
        }),
      );
    } else if (url.pathname === '/api/loop') {
      streamLoop(res, url.searchParams);
    } else if (url.pathname === '/api/replay') {
      replayFromParams(url.searchParams).then(
        (r) => res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify(r)),
        (err) => res.writeHead(400, { 'content-type': 'application/json' }).end(JSON.stringify({ error: err instanceof Error ? err.message : String(err) })),
      );
    } else if (url.pathname === '/api/artifact') {
      serveArtifact(res, url.searchParams);
    } else if (url.pathname === '/theme.css') {
      res.writeHead(200, { 'content-type': 'text/css; charset=utf-8', 'cache-control': 'no-cache' });
      res.end(readFileSync(new URL('./dashboard/theme.css', import.meta.url)));
    } else if (url.pathname === '/badge.svg') {
      if (!existsSync('.bulwark/badge.svg')) return res.writeHead(404).end('no badge yet');
      res.writeHead(200, { 'content-type': 'image/svg+xml', 'cache-control': 'no-cache' });
      res.end(readFileSync('.bulwark/badge.svg'));
    } else if (url.pathname === '/api/run') {
      streamRun(res, url.searchParams).catch((err) => {
        send(res, 'error', { message: err instanceof Error ? err.message : String(err) });
        res.end();
      });
    } else {
      res.writeHead(404).end('not found');
    }
  }).listen(PORT, () => {
    console.log(`Bulwark dashboard → http://localhost:${PORT}  (neatlogs ${exporting ? 'exporting' : 'local only'})`);
  });
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
// Trial replay: every trial is reproducible from its seed, so re-running one
// with the recorder on gives its full step-by-step story (brain decisions, tool
// calls, injected faults, retries, side effects, outcome, broken rules).

import { existsSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { getFault } from './chaos/faults';
import { runTrial, type TrialObservation } from './harness';
import { compileRules } from './invariants';
import type { TrialEvent } from './recorder';
import { loadTarget, type BulwarkTarget } from './target';

export interface ReplayResult {
  target: string;
  fault: string;
  seed: number;
  /** Where the code came from: the original target dir, or a loop workspace (patched code). */
  source: string;
  observation: Omit<TrialObservation, 'timeline'>;
  broken: { rule: string; how: string; detail?: string }[];
  timeline: TrialEvent[];
}

/** Same settings the dashboard and the loop use, so a replay matches the square that was clicked. */
export const REPLAY_DEFAULTS = { brain: 'simulated' as const, deadlineMs: 5000, maxSteps: 50 };

const SAFE = /^[\w-]{1,128}$/;

/**
 * Turns untrusted query parameters into a target directory, or throws.
 * - `run` + `ws`: a loop workspace, `.bulwark/runs/<run>/ws/<ws>` (e.g. ws = "timeout-after-commit-accepted").
 * - `target`: a directory under `targets/` ("refundbot" or "targets/refundbot").
 * Only plain names are accepted, so nothing can climb out of those roots.
 */
export function resolveReplayDir(params: { target?: string | null; run?: string | null; ws?: string | null }, stateDir = '.bulwark'): string {
  const { run, ws } = params;
  if (run || ws) {
    if (!run || !ws || !SAFE.test(run) || !SAFE.test(ws)) throw new Error('run and ws must both be plain names');
    const root = resolve(stateDir, 'runs');
    const dir = resolve(root, run, 'ws', ws);
    if (!dir.startsWith(root + sep)) throw new Error('workspace outside the runs directory');
    if (!existsSync(join(dir, 'bulwark.target.ts'))) throw new Error(`no workspace ${run}/${ws}`);
    return dir;
  }
  const name = (params.target ?? 'targets/refundbot').replace(/^targets\//, '');
  if (!SAFE.test(name)) throw new Error('target must be a directory name under targets/');
  const root = resolve('targets');
  const dir = resolve(root, name);
  if (!dir.startsWith(root + sep) || !existsSync(join(dir, 'bulwark.target.ts'))) throw new Error(`unknown target ${name}`);
  return dir;
}

export async function replayTrial(args: {
  target: BulwarkTarget;
  fault: string;
  seed: number;
  source?: string;
  deadlineMs?: number;
  maxSteps?: number;
}): Promise<ReplayResult> {
  const fault = args.fault === 'baseline' ? undefined : getFault(args.fault);
  if (!Number.isInteger(args.seed) || args.seed < 0 || args.seed > 0xffffffff) throw new Error('seed must be a 32-bit unsigned integer');
  const { compiled, uncompiled } = compileRules(args.target.rules);
  if (uncompiled.length) throw new Error(`could not compile rules: ${uncompiled.join(' | ')}`);

  const obs = await runTrial({
    ...REPLAY_DEFAULTS,
    ...(args.deadlineMs ? { deadlineMs: args.deadlineMs } : {}),
    ...(args.maxSteps ? { maxSteps: args.maxSteps } : {}),
    target: args.target,
    fault,
    seed: args.seed,
    traced: false,
    record: true,
  });
  const { timeline = [], ...observation } = obs;
  const broken = compiled.flatMap(({ rule, how, check }) => {
    const res = check(obs);
    return res.ok ? [] : [{ rule, how, detail: res.detail }];
  });
  return { target: args.target.name, fault: fault?.id ?? 'baseline', seed: args.seed, source: args.source ?? args.target.name, observation, broken, timeline };
}

/** For the API: validates the parameters, loads the right code, replays. */
export async function replayFromParams(params: URLSearchParams): Promise<ReplayResult> {
  const fault = params.get('fault') ?? '';
  const seedStr = params.get('seed') ?? '';
  if (!/^\d{1,10}$/.test(seedStr)) throw new Error('seed must be a non-negative integer');
  const dir = resolveReplayDir({ target: params.get('target'), run: params.get('run'), ws: params.get('ws') });
  const run = params.get('run');
  const source = run ? `.bulwark/runs/${run}/ws/${params.get('ws')}` : `targets/${dir.split(sep).pop()}`;
  return replayTrial({ target: await loadTarget(dir), fault, seed: Number(seedStr), source });
}

const short = (v: unknown, n = 140) => {
  const s = typeof v === 'string' ? JSON.stringify(v) : JSON.stringify(v) ?? String(v);
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};

/** One line per event, for the terminal. */
export function describeEvent(e: TrialEvent): string {
  switch (e.type) {
    case 'brain':
      return e.decision.type === 'tool'
        ? `brain    step ${e.step}: call ${e.decision.name} ${short(e.decision.input)}`
        : `brain    step ${e.step}: final reply ${short(e.decision.reply)}`;
    case 'call':
      return `tool  →  #${e.call} ${e.endpoint} ${short(e.input)}${e.retryOf ? `  (RETRY of #${e.retryOf}, attempt ${e.attempt})` : ''}`;
    case 'result':
      return `tool  ←  #${e.call} ${e.endpoint} ${short(e.output)} (${e.ms}ms)${e.late ? '  LATE: agent already gave up' : ''}`;
    case 'error':
      return `tool  ✗  #${e.call} ${e.endpoint} ERROR ${e.error} (${e.ms}ms)${e.late ? '  (late)' : ''}`;
    case 'timeout':
      return `timeout  #${e.call} ${e.endpoint}: ${e.detail}`;
    case 'fault':
      return `FAULT    ${e.fault} on #${e.call} ${e.endpoint}: ${e.detail}`;
    case 'effect':
      return `effect   ${e.effect}: ${short(e.data)}`;
    case 'outcome':
      return `outcome  ${e.outcome.toUpperCase()} after ${e.steps} steps, ${e.durationMs}ms${e.error ? ` · error: ${e.error}` : ''}${e.reply ? ` · reply: ${short(e.reply)}` : ''}`;
  }
}
// Opt-in, per-trial event recorder for the replay viewer. It watches a trial at
// three points: the brain's decisions, the wire as the agent sees it (after any
// fault), and the wire as the services see it (before any fault, where side
// effects land in the sandbox ledger). It never touches randomness or results,
// so a recorded trial behaves exactly like an unrecorded one with the same seed.

import type { Decision } from '../targets/refundbot/agent';
import type { Endpoint, PaymentsSandbox, Transport } from '../targets/refundbot/payments';
import type { FaultEvent } from './chaos/faults';

interface Base {
  /** Position in the timeline. */
  i: number;
  /** Milliseconds since the trial started. Wall-clock, so it is not part of the deterministic replay. */
  t: number;
}

export type TrialEvent = Base &
  (
    | { type: 'brain'; step: number; decision: Decision }
    | { type: 'call'; call: number; endpoint: Endpoint; input: Record<string, unknown>; attempt: number; retryOf?: number }
    | { type: 'result'; call: number; endpoint: Endpoint; output: unknown; ms: number; late?: boolean }
    | { type: 'error'; call: number; endpoint: Endpoint; error: string; ms: number; late?: boolean }
    | { type: 'timeout'; call: number; endpoint: Endpoint; afterMs: number; detail: string }
    | { type: 'fault'; call: number; fault: string; kind: string; endpoint: Endpoint; detail: string }
    | { type: 'effect'; effect: 'refund' | 'email'; data: unknown }
    | { type: 'outcome'; outcome: string; error?: string; reply?: string; steps: number; durationMs: number }
  );

type Draft = TrialEvent extends infer E ? (E extends TrialEvent ? Omit<E, 'i' | 't'> : never) : never;

const parse = (raw: string): unknown => {
  try {
    return JSON.parse(raw);
  } catch {
    return raw; // e.g. truncated JSON: show exactly what the agent received
  }
};

export class TrialRecorder {
  readonly events: TrialEvent[] = [];
  private start = performance.now();
  private stopped = false;
  private calls = 0;
  /** The call the agent is currently making, so a fault fired inside it can point back to it. */
  private current = 0;
  private pending = new Map<number, { endpoint: Endpoint; at: number; superseded: boolean }>();
  private attempts = new Map<Endpoint, number>();

  private now = () => performance.now() - this.start;

  private push(e: Draft) {
    if (this.stopped) return;
    this.events.push({ i: this.events.length, t: Math.round(this.now()), ...e } as TrialEvent);
  }

  /** Freezes the timeline; anything a wound-down run does afterwards is ignored. */
  stop() {
    this.stopped = true;
  }

  brain(step: number, decision: Decision) {
    this.push({ type: 'brain', step, decision });
  }

  /** For FaultContext.onEvent. */
  fault = (e: FaultEvent) => {
    this.push({ type: 'fault', call: this.current, fault: e.fault, kind: e.kind, endpoint: e.endpoint, detail: e.title });
  };

  outcome(o: { outcome: string; error?: string; reply?: string; steps: number; durationMs: number }) {
    // Calls nobody is waiting on any more: a timed-out request, or the one a hung run was stuck on.
    for (const [call, p] of this.pending) {
      if (p.superseded) continue;
      p.superseded = true;
      const afterMs = Math.round(this.now() - p.at);
      this.push({ type: 'timeout', call, endpoint: p.endpoint, afterMs, detail: `call #${call} still in flight after ~${afterMs}ms when the run ended (${o.outcome})` });
    }
    const { outcome, error, reply, steps } = o;
    this.push({ type: 'outcome', outcome, ...(error ? { error } : {}), ...(reply !== undefined ? { reply } : {}), steps, durationMs: Math.round(o.durationMs) });
  }

  /** Wraps the transport the agent calls (outermost, after fault injection). */
  agentSide(transport: Transport): Transport {
    return async (endpoint, payload) => {
      const call = ++this.calls;
      const at = this.now();
      // The agent never tells the wire it gave up, but a second call to the same
      // endpoint while the first is still in flight means it timed out and retried.
      const inFlight = [...this.pending].filter(([, p]) => p.endpoint === endpoint && !p.superseded);
      let retryOf: number | undefined;
      for (const [id, p] of inFlight) {
        p.superseded = true;
        retryOf = id;
        const afterMs = Math.round(at - p.at);
        this.push({
          type: 'timeout',
          call: id,
          endpoint,
          afterMs,
          detail: `agent stopped waiting for call #${id} after ~${afterMs}ms; the request is still in flight`,
        });
      }
      const attempt = (this.attempts.get(endpoint) ?? 0) + 1;
      this.attempts.set(endpoint, attempt);
      this.pending.set(call, { endpoint, at, superseded: false });
      this.push({ type: 'call', call, endpoint, input: payload, attempt, ...(retryOf ? { retryOf } : {}) });

      this.current = call;
      const res = transport(endpoint, payload);
      this.current = 0;
      try {
        const raw = await res;
        const p = this.pending.get(call)!;
        this.push({ type: 'result', call, endpoint, output: parse(raw), ms: Math.round(this.now() - at), ...(p.superseded ? { late: true } : {}) });
        return raw;
      } catch (err) {
        const p = this.pending.get(call)!;
        const error = err instanceof Error ? err.message : String(err);
        this.push({ type: 'error', call, endpoint, error, ms: Math.round(this.now() - at), ...(p.superseded ? { late: true } : {}) });
        throw err;
      } finally {
        this.pending.delete(call);
      }
    };
  }

  /** Wraps the services' transport (innermost, before fault injection) to catch real side effects. */
  serviceSide(transport: Transport, sandbox: PaymentsSandbox): Transport {
    return async (endpoint, payload) => {
      const refunds = sandbox.refunds.length;
      const emails = sandbox.emails.length;
      try {
        return await transport(endpoint, payload);
      } finally {
        for (const r of sandbox.refunds.slice(refunds)) this.push({ type: 'effect', effect: 'refund', data: { ...r } });
        for (const e of sandbox.emails.slice(emails)) this.push({ type: 'effect', effect: 'email', data: { ...e } });
      }
    };
  }
}

/** The timeline without wall-clock fields: what must be identical across replays of one seed. */
export function stableTimeline(events: TrialEvent[]): unknown[] {
  return events.map(({ t: _t, ...e }) => {
    const { ms: _ms, afterMs: _a, durationMs: _d, detail, ...rest } = e as Record<string, unknown>;
    // Timeout details embed a wall-clock duration; the rest of the detail text is stable.
    return e.type === 'timeout' ? rest : { ...rest, ...(detail !== undefined ? { detail } : {}) };
  });
}
// npm run replay -- --fault timeout-after-commit --seed <n> [--target refundbot] [--run <runId> --ws <label>] [--json]
//
// Re-runs one trial from its seed with the recorder on and prints its timeline.

import { parseArgs } from 'node:util';
import { describeEvent, replayFromParams } from './replay';

async function main() {
  const { values } = parseArgs({
    options: {
      fault: { type: 'string', default: 'timeout-after-commit' },
      seed: { type: 'string' },
      target: { type: 'string' },
      run: { type: 'string' },
      ws: { type: 'string' },
      json: { type: 'boolean', default: false },
    },
  });
  if (!values.seed) throw new Error('--seed is required (find one in a scorecard\'s "replayable failures")');
  const params = new URLSearchParams();
  for (const k of ['fault', 'seed', 'target', 'run', 'ws'] as const) if (values[k]) params.set(k, values[k]!);

  const r = await replayFromParams(params);
  if (values.json) return console.log(JSON.stringify(r, null, 2));

  console.log(`Replay ${r.fault} · seed ${r.seed} · ${r.source}\n`);
  for (const e of r.timeline) console.log(`${String(e.t).padStart(6)}ms  ${describeEvent(e)}`);
  console.log('');
  if (r.broken.length === 0) console.log('✓ every rule held');
  for (const b of r.broken) console.log(`✗ ${b.rule}\n    ${b.detail ?? ''}\n    how it's checked: ${b.how}`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

// Judge agent: decides whether a patch actually works. It never sees the fixer's
// reasoning. It loads the patched code from its own workspace, re-runs the
// attack and every other attack on the Judge's own seeds, and compares against
// the unpatched code on those exact seeds.

import { trace } from 'neatlogs';
import { FAULTS, type Fault } from '../chaos/faults';
import type { TrialObservation } from '../harness';
import { runExperiment, type ExperimentOptions, type ExperimentResult } from '../scorecard';
import { fisherGreater } from '../stats';
import type { BulwarkTarget } from '../target';
import { compareOverhead, hasBudgets, perfOf, type CostFn, type Overhead, type OverheadBudgets, type Perf } from './overhead';
import { describeSlo, evaluateSlo, type SloPlan, type SloResult } from './slo';

export type VerdictStatus = 'fixed' | 'inconclusive' | 'rejected';

export interface Regression {
  fault: string;
  before: number;
  after: number;
  trials: number;
  pValue: number;
}

export interface Verdict {
  status: VerdictStatus;
  reasons: string[];
  before: ExperimentResult;
  after: ExperimentResult;
  /** P(this improvement is luck). */
  pValue: number;
  regressions: Regression[];
  /** Every fault's result on the patched code (baseline included). */
  results: Record<string, MeasuredResult>;
  /** Present when an SLO was set for this fault: whether the after-fix trials demonstrate it. */
  slo?: SloResult;
  /** What the fix costs vs the unpatched code (happy path), and whether it fits the budgets. */
  overhead?: Overhead;
}

/** An experiment result plus the latency/steps/cost profile of its trials. */
export type MeasuredResult = ExperimentResult & { perf?: Perf };

const SIGNIFICANCE = 0.05;

/** "Fixed with overhead": the fix works but exceeds an overhead budget under the "flag" policy. */
export const fixedWithOverhead = (v: Pick<Verdict, 'status' | 'overhead'>) => v.status === 'fixed' && v.overhead?.withinBudget === false;

/**
 * Runs the baseline plus every fault in the catalog against one version of the
 * code, recording each experiment's latency/steps/cost profile. `trialsFor` lets
 * one experiment (e.g. the fault under an SLO) run a different number of trials.
 */
export async function runAll(
  target: BulwarkTarget,
  opts: ExperimentOptions,
  trialsFor?: (fault: string) => number | undefined,
  cost?: CostFn,
): Promise<Record<string, MeasuredResult>> {
  const measure = async (f: Fault | undefined): Promise<MeasuredResult> => {
    const id = f?.id ?? 'baseline';
    const obs: TrialObservation[] = [];
    const r = await runExperiment(target, f, {
      ...opts,
      trials: trialsFor?.(id) ?? opts.trials,
      onTrial: (t) => {
        obs.push(t.obs);
        opts.onTrial?.(t);
      },
    });
    return { ...r, perf: perfOf(obs, cost) };
  };
  // The baseline runs on its own first: it is the happy path the overhead budgets
  // are checked on, so its latency must not depend on how busy the fault runs are.
  const baseline = await measure(undefined);
  const faults = await Promise.all(FAULTS.map(measure));
  return Object.fromEntries([baseline, ...faults].map((r) => [r.fault, r]));
}

export async function judge(args: {
  fault: Fault;
  candidate: () => Promise<BulwarkTarget>;
  baseResults: Record<string, MeasuredResult>;
  opts: ExperimentOptions;
  /** Reliability target for this fault: the after-fix run uses exactly `slo.trials` trials. */
  slo?: SloPlan;
  /** Optional overhead budgets; overhead is always measured and reported. */
  budgets?: OverheadBudgets;
  cost?: CostFn;
}): Promise<Verdict> {
  const { fault, baseResults, opts, slo, budgets } = args;
  const before = baseResults[fault.id];

  return trace({ name: 'judge.verify', kind: 'AGENT', attributes: { fault: fault.id } }, async () => {
    let target: BulwarkTarget;
    try {
      target = await args.candidate();
    } catch (err) {
      const reason = `patched code failed to load: ${err instanceof Error ? err.message.split('\n')[0] : err}`;
      return { status: 'rejected', reasons: [reason], before, after: before, pValue: 1, regressions: [], results: {} };
    }

    // The fault under test runs the SLO's trial count when one is set. Every other
    // experiment keeps the trial count of its baseline, so comparisons stay like for like.
    const results = await runAll(target, opts, (id) => (id === fault.id ? slo?.trials : baseResults[id]?.trials), args.cost);
    const after = results[fault.id];
    const pValue = fisherGreater(after.passed, after.trials, before.passed, before.trials);
    const reasons: string[] = [];

    const regressions: Regression[] = [];
    for (const [id, r] of Object.entries(results)) {
      if (id === fault.id) continue;
      const b = baseResults[id];
      const p = fisherGreater(b.passed, b.trials, r.passed, r.trials);
      if (r.passRate < b.passRate && (p < SIGNIFICANCE * 2 || id === 'baseline')) {
        regressions.push({ fault: id, before: b.passed, after: r.passed, trials: r.trials, pValue: p });
      }
    }

    const broken = Object.entries(after.violations)
      .filter(([, n]) => n > 0)
      .map(([rule, n]) => `${n}× ${rule}`);

    const sloResult = slo ? evaluateSlo(slo, after.passed, after.trials) : undefined;
    const base = baseResults.baseline;
    const overhead =
      base?.perf && results.baseline?.perf
        ? {
            ...compareOverhead(base.perf, results.baseline.perf, budgets),
            ...(before.perf && after.perf ? { underFault: { before: before.perf, after: after.perf } } : {}),
          }
        : undefined;

    let status: VerdictStatus;
    if (regressions.length) {
      status = 'rejected';
      for (const r of regressions) reasons.push(`regressed ${r.fault}: ${r.before}/${r.trials} → ${r.after}/${r.trials}`);
    } else if (after.passed < after.trials) {
      status = 'rejected';
      reasons.push(`still failing ${after.trials - after.passed}/${after.trials} trials (${broken.join('; ')})`);
    } else if (pValue >= SIGNIFICANCE) {
      status = 'inconclusive';
      reasons.push(`all trials passed, but the improvement over ${before.passed}/${before.trials} is not significant (p=${pValue.toFixed(3)})`);
    } else {
      status = 'fixed';
      reasons.push(`${before.passed}/${before.trials} → ${after.passed}/${after.trials} on fresh seeds (p=${pValue.toExponential(1)}), no regressions`);
    }

    if (sloResult) reasons.push(describeSlo(sloResult));
    if (overhead && hasBudgets(budgets) && !overhead.withinBudget) {
      // Only a fix that otherwise works can be "fixed with overhead"; a failing fix stays rejected for its failures.
      if (status === 'fixed' && (budgets?.policy ?? 'reject') === 'reject') {
        status = 'rejected';
        reasons.push(`overhead over budget: ${overhead.exceeded.join('; ')}`);
      } else if (status === 'fixed') {
        reasons.push(`fixed with overhead: ${overhead.exceeded.join('; ')}`);
      } else {
        reasons.push(`also over the overhead budget: ${overhead.exceeded.join('; ')}`);
      }
    }
    return {
      status,
      reasons,
      before,
      after,
      pValue,
      regressions,
      results,
      ...(sloResult ? { slo: sloResult } : {}),
      ...(overhead ? { overhead } : {}),
    };
  });
}
// Guard: every accepted fix ships with a chaos regression test, and the test is
// itself proven: it must fail on the un-fixed code and pass on the fixed code.
// A test that passes either way protects nothing.

import { getFault } from './chaos/faults';
import { runExperiment, type ExperimentOptions, type ExperimentResult } from './scorecard';
import type { BulwarkTarget } from './target';
import type { Files } from './workspace';

export interface ChaosSpec {
  fault: string;
  trials: number;
  seed: number;
  strategy: string;
  createdBy: 'bulwark';
}

export const specPath = (fault: string) => `chaos-tests/${fault}.json`;

export function withSpec(files: Files, spec: ChaosSpec): Files {
  return { ...files, [specPath(spec.fault)]: JSON.stringify(spec, null, 2) + '\n' };
}

export interface MutationCheck {
  ok: boolean;
  unfixed: ExperimentResult;
  fixed: ExperimentResult;
}

export async function mutationCheck(
  spec: ChaosSpec,
  unfixed: BulwarkTarget,
  fixed: BulwarkTarget,
  base: ExperimentOptions,
): Promise<MutationCheck> {
  const opts = { ...base, trials: spec.trials, seed: spec.seed, onTrial: undefined };
  const fault = getFault(spec.fault);
  const [u, f] = await Promise.all([runExperiment(unfixed, fault, opts), runExperiment(fixed, fault, opts)]);
  return { ok: u.passed < u.trials && f.passed === f.trials, unfixed: u, fixed: f };
}
// npm run chaos -- [--fault <id>|all] [--trials 20] [--seed 42] [--brain simulated|claude]
//                  [--generated [--generated-file .bulwark/generated-faults.json]]
//
// Attacks the target agent with each fault, N trials apiece, and writes a
// scorecard to runs/<timestamp>/.

import './env';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseArgs } from 'node:util';
import { target } from '../targets/refundbot/bulwark.target';
import { FAULTS, getFault, registerFaults, type Fault } from './chaos/faults';
import { CostMeter, usd } from './cost/meter';
import { loadPriceBook } from './cost/pricing';
import { GENERATED_FAULTS_PATH, loadGeneratedFaults } from './red/generate';
import type { BrainMode } from './harness';
import { renderConsole, renderMarkdown, runExperiment, type ExperimentResult } from './scorecard';
import { llmProvider } from './llm';
import { initTracing, shutdownTracing } from './tracing';

async function main() {
  const { values } = parseArgs({
    options: {
      fault: { type: 'string', default: 'all' },
      trials: { type: 'string', default: '20' },
      seed: { type: 'string', default: '42' },
      brain: { type: 'string', default: 'simulated' },
      deadline: { type: 'string', default: '5000' },
      'max-steps': { type: 'string', default: '50' },
      generated: { type: 'boolean', default: false },
      'generated-file': { type: 'string', default: GENERATED_FAULTS_PATH },
    },
  });
  if (values.generated) {
    const added = registerFaults(loadGeneratedFaults(values['generated-file']));
    console.log(`+ ${added.filter((f) => f.spec).length} generated faults from ${values['generated-file']}`);
  }
  const brain = values.brain as BrainMode;
  if (brain !== 'simulated' && brain !== 'claude') throw new Error('--brain must be "simulated" or "claude"');
  if (brain === 'claude' && !llmProvider()) throw new Error('--brain claude needs ZG_ROUTER_API_KEY or ANTHROPIC_API_KEY');

  const faults: (Fault | undefined)[] =
    values.fault === 'all' ? [undefined, ...FAULTS] : [undefined, getFault(values.fault!)];
  const opts = {
    trials: Number(values.trials),
    seed: Number(values.seed),
    brain,
    deadlineMs: Number(values.deadline),
    maxSteps: Number(values['max-steps']),
    sessionId: `chaos-${new Date().toISOString().replace(/[:.]/g, '-')}`,
  };

  const exporting = await initTracing('bulwark-chaos');
  console.log(
    `Bulwark → ${target.name} | ${opts.trials} trials/fault | seed ${opts.seed} | brain ${brain} | neatlogs ${exporting ? 'exporting' : 'local only (no NEATLOGS_API_KEY)'}\n`,
  );

  const results: ExperimentResult[] = [];
  const meter = new CostMeter();
  await meter.run(async () => {
    for (const fault of faults) {
      process.stdout.write(`  attacking: ${fault?.id ?? 'baseline'}… `);
      const r = await runExperiment(target, fault, opts);
      console.log(`${r.passed}/${r.trials} passed`);
      results.push(r);
    }
  });
  const book = await loadPriceBook({ provider: llmProvider() });
  const cost = meter.summarize(book.priceFor, `0G router prices (${book.zgSource}); Anthropic-direct static table`);
  console.log('\n' + renderConsole(results) + '\n');
  console.log(`Cost ${usd(cost.totalUsd)} = LLM ${usd(cost.llmUsd)} (${cost.calls} calls) + compute ${usd(cost.computeUsd)} (${Math.round(cost.wallMs / 1000)}s) over ${cost.trials} trials\n`);

  const dir = join('runs', new Date().toISOString().replace(/[:.]/g, '-'));
  mkdirSync(dir, { recursive: true });
  const meta = { trials: opts.trials, seed: opts.seed, brain, date: new Date().toISOString() };
  writeFileSync(join(dir, 'scorecard.json'), JSON.stringify({ target: target.name, ...meta, results, cost }, null, 2));
  writeFileSync(join(dir, 'scorecard.md'), renderMarkdown(target, results, meta));
  console.log(`Scorecard written to ${dir}/`);

  await shutdownTracing();
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
// npm run fix -- [--fault <id>|all] [--fixer auto|playbook|claude] [--red-trials 20]
//                [--judge-trials 40] [--seed 42] [--max-attempts 4] [--no-memory] [--apply] [--pr] [--generated]
//                [--slo 0.99[,<fault>=0.999]] [--slo-confidence 0.95] [--max-slo-trials 1000]
//                [--max-latency-overhead 50%] [--max-step-overhead 2] [--max-cost-overhead 20%] [--overhead-policy reject|flag]
//                [--tournament claude-sonnet-5,deepseek-v4-flash | playbook,playbook-strong]
//                [--neatlogs-wait 20]  seconds Blue waits for a failing trial's neatlogs trace (0 = don't read back)
//
// The full loop: attack, fix, verify, prove. Writes artifacts to .bulwark/runs/<id>/.

import './env';
import { parseArgs } from 'node:util';
import { usd } from './cost/meter';
import { registerFaults } from './chaos/faults';
import { loadGeneratedFaults } from './red/generate';
import { fixedWithOverhead } from './judge/judge';
import { describeOverhead, parsePercent, type OverheadBudgets } from './judge/overhead';
import { DEFAULT_MAX_SLO_TRIALS, DEFAULT_SLO_CONFIDENCE, describePlan, fmtRate, parseSlo } from './judge/slo';
import { parseTournament } from './judge/tournament';
import { applyAsBranch, DEFAULT_LOOP, openPullRequest, runLoop, type LoopEvent } from './loop/orchestrator';
import { describeObserve } from './observe/evidence';
import { summarizeProvenance } from './provenance/entire';
import { describeBlast } from './red/graph';
import { money } from './risk';
import { initTracing, shutdownTracing } from './tracing';

const c = {
  dim: (s: string) => `\x1b[2m${s}\x1b[0m`,
  red: (s: string) => `\x1b[31m${s}\x1b[0m`,
  green: (s: string) => `\x1b[32m${s}\x1b[0m`,
  yellow: (s: string) => `\x1b[33m${s}\x1b[0m`,
  blue: (s: string) => `\x1b[34m${s}\x1b[0m`,
  bold: (s: string) => `\x1b[1m${s}\x1b[0m`,
};
const pct = (x: number) => `${Math.round(x * 100)}%`;

let allPassAfter = true;

function print(e: LoopEvent) {
  switch (e.type) {
    case 'run-start':
      return console.log(c.bold(`Bulwark loop → ${e.target}`) + c.dim(` | fixer ${e.fixer} | red ${e.redTrials} trials, judge ${e.judgeTrials} trials | run ${e.runId}\n`));
    case 'analyze':
      console.log(c.red('RED') + ` found ${e.findings.length} weak links:`);
      for (const f of e.findings) {
        console.log(`  ${f.severity === 'high' ? c.red('high') : c.yellow('med ')}  ${f.file}:${f.line}  ${f.why}`);
        if (f.blast) console.log(c.dim(`        blast radius (Entire Graph): ${describeBlast(f.blast)}`));
      }
      for (const line of summarizeProvenance(e.provenance ?? [])) console.log(c.dim(`  provenance: ${line}`));
      return console.log();
    case 'scorecard': {
      if (e.phase === 'after') allPassAfter = e.results.every((r) => r.passed === r.trials);
      const label = e.phase === 'before' ? c.red('RED') + ' scorecard (before)' : c.bold('Scorecard after fixes');
      console.log(`${label}: overall ${pct(e.overall)} of trials kept every rule`);
      for (const r of e.results) {
        const risk = r.dollarsAtRisk ? c.dim(`  ${money(r.dollarsAtRisk.per1kTickets)} at risk / 1k tickets`) : '';
        console.log(`  ${r.fault.padEnd(22)} ${(r.passed === r.trials ? c.green : c.red)(`${r.passed}/${r.trials}`.padEnd(6))}${risk}`);
      }
      return console.log();
    }
    case 'fault-start':
      return console.log(c.bold(`▶ ${e.fault}`) + c.dim(`  ${e.hypothesis}`));
    case 'observe': {
      const tag = e.status === 'read' ? c.green('read') : e.status === 'pending' ? c.yellow('pending') : c.dim('unavailable');
      return console.log(`  ${c.dim('OBSERVE')} neatlogs ${tag}: ${c.dim(describeObserve(e))}`);
    }
    case 'fault-skip':
      return console.log(c.dim(`  skipped: ${e.reason}`));
    case 'checkpoint':
      return console.log(c.dim(`  ${e.action === 'save' ? '⎘ checkpoint' : '↺ rolled back to'} ${e.id}`));
    case 'slo-plan':
      console.log(c.bold(`SLO plan`) + c.dim(` (${fmtRate(e.confidence)} confidence, ${e.method})`));
      for (const p of e.plans) console.log(`  ${describePlan(p)}`);
      return console.log();
    case 'attempt':
      return console.log(`  ${c.blue('BLUE')} ${e.round ? `round ${e.round} candidate` : 'attempt'} ${e.n}: ${e.title} ${c.dim(`(${e.strategy}, ${e.author}, +${e.added}/-${e.removed})`)}`);
    case 'verdict': {
      const tag =
        e.status === 'fixed' ? (fixedWithOverhead(e) ? c.yellow('FIXED WITH OVERHEAD') : c.green('FIXED')) : e.status === 'inconclusive' ? c.yellow('INCONCLUSIVE') : c.red('REJECTED');
      console.log(`  ${c.yellow('JUDGE')} ${tag} ${e.reasons.join('; ')}`);
      if (e.overhead) console.log(c.dim(`        overhead: ${describeOverhead(e.overhead)}`));
      return;
    }
    case 'tournament': {
      console.log(`  ${c.bold('TOURNAMENT')} round ${e.round}: ${e.winner ? c.green(`${e.winner} wins`) : c.red('no winner')}`);
      for (const r of e.ranking) console.log(`    ${r.rank}. ${r.entrant.padEnd(18)} ${(r.strategy ?? '—').padEnd(26)} ${r.outcome === 'winner' ? c.green(r.outcome) : c.dim(r.outcome)}: ${r.reason}`);
      return;
    }
    case 'mutation':
      return console.log(`  ${c.dim('GUARD')} regression test without fix ${e.unfixedPassed}/${e.trials}, with fix ${e.fixedPassed}/${e.trials} ${e.ok ? c.green('✓ proven') : c.red('✗ not proven')}`);
    case 'fault-done':
      return console.log();
    case 'residual':
      if (e.findings.length === 0) return console.log(c.green('No weak links remain in the final code.\n'));
      console.log(c.yellow(`Remaining risk (${e.findings.length}):`) + (allPassAfter ? ' every attack passes, but the analyzer still sees:' : ' the analyzer still sees:'));
      for (const f of e.findings) console.log(`  ${f.file}:${f.line}  ${f.why}`);
      return console.log();
    case 'log':
      return console.log(c.dim(`  ${e.message}`));
    case 'run-done': {
      const s = e.summary;
      console.log(c.bold(`Resilience ${pct(s.overallBefore)} → ${pct(s.overallAfter)}`) + `  fixed ${s.fixed.length}, unfixed ${s.unfixed.length}, skipped ${s.skipped.length} · ${s.attempts} attempts, ${s.rollbacks} rollbacks`);
      if (s.cost) {
        const k = s.cost;
        console.log(`Run cost ${c.bold(usd(k.totalUsd))}` + c.dim(` = LLM ${usd(k.llmUsd)} (${k.calls} calls, ${k.inputTokens + k.outputTokens} tokens) + compute ${usd(k.computeUsd)} (${Math.round(k.wallMs / 1000)}s) · ${k.trials} trials`));
      }
      return console.log(c.dim(`Artifacts: ${s.dir}/ (fix.patch, PR.md, postmortem-*.md, badge.svg, summary.json)`));
    }
  }
}

async function main() {
  const { values } = parseArgs({
    options: {
      fault: { type: 'string', default: 'all' },
      fixer: { type: 'string', default: DEFAULT_LOOP.fixer },
      'red-trials': { type: 'string', default: String(DEFAULT_LOOP.redTrials) },
      'judge-trials': { type: 'string', default: String(DEFAULT_LOOP.judgeTrials) },
      seed: { type: 'string', default: String(DEFAULT_LOOP.seed) },
      'max-attempts': { type: 'string', default: String(DEFAULT_LOOP.maxAttempts) },
      'no-memory': { type: 'boolean', default: false },
      apply: { type: 'boolean', default: false },
      pr: { type: 'boolean', default: false },
      target: { type: 'string', default: 'targets/refundbot' },
      generated: { type: 'boolean', default: false },
      slo: { type: 'string' },
      'slo-confidence': { type: 'string', default: String(DEFAULT_SLO_CONFIDENCE) },
      'max-slo-trials': { type: 'string', default: String(DEFAULT_MAX_SLO_TRIALS) },
      'max-latency-overhead': { type: 'string' },
      'max-step-overhead': { type: 'string' },
      'max-cost-overhead': { type: 'string' },
      'overhead-policy': { type: 'string', default: 'reject' },
      tournament: { type: 'string' },
      'neatlogs-wait': { type: 'string' },
    },
  });
  // Generative Red's accepted faults join the catalog, so Red, Blue, Judge and Guard all see them.
  if (values.generated) registerFaults(loadGeneratedFaults());
  const slo = values.slo ? parseSlo(values.slo, Number(values['slo-confidence']), Number(values['max-slo-trials'])) : undefined;
  const policy = values['overhead-policy'] as 'reject' | 'flag';
  if (!['reject', 'flag'].includes(policy)) throw new Error('--overhead-policy must be reject or flag');
  const budgets: OverheadBudgets = {
    policy,
    ...(values['max-latency-overhead'] ? { maxLatencyOverhead: parsePercent(values['max-latency-overhead']) } : {}),
    ...(values['max-step-overhead'] ? { maxStepOverhead: Number(values['max-step-overhead']) } : {}),
    ...(values['max-cost-overhead'] ? { maxCostOverhead: parsePercent(values['max-cost-overhead']) } : {}),
  };
  if (budgets.maxStepOverhead !== undefined && !(budgets.maxStepOverhead >= 0)) throw new Error('--max-step-overhead must be a number of steps, e.g. 2');
  const tournament = values.tournament ? parseTournament(values.tournament) : undefined;
  const fixer = values.fixer as 'auto' | 'playbook' | 'claude';
  if (!['auto', 'playbook', 'claude'].includes(fixer)) throw new Error('--fixer must be auto, playbook or claude');

  await initTracing('bulwark-loop');
  const summary = await runLoop(
    {
      targetDir: values.target!,
      faults: values.fault === 'all' ? 'all' : values.fault!.split(','),
      fixer,
      redTrials: Number(values['red-trials']),
      judgeTrials: Number(values['judge-trials']),
      seed: Number(values.seed),
      maxAttempts: Number(values['max-attempts']),
      memory: !values['no-memory'],
      slo,
      budgets,
      tournament,
      ...(values['neatlogs-wait'] !== undefined ? { readbackWaitMs: Number(values['neatlogs-wait']) * 1000 } : {}),
    },
    print,
  );

  if ((values.apply || values.pr) && summary.fixed.length) {
    const branch = applyAsBranch(summary);
    console.log(c.green(`Committed verified fixes to branch ${branch}`));
    if (values.pr) console.log(c.green(`Opened ${openPullRequest(branch, summary)}`));
  }
  await shutdownTracing();
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});

